import data from "@/data/circuits/catalog.json";

/**
 * The circuit library: one entry per circuit with a Grand Prix in the OpenF1 era (2023 onwards). Generated by tools/circuit-catalog
 * from Wikipedia (circuit facts, lap records) and OpenF1 (circuit keys, Grands Prix held); every field keeps its source in `sources`.
 * This is the single source of circuit identity for the site: pages, links from results and the race view all resolve through it.
 */
export type CircuitType = "street" | "permanent" | "road";
export type CircuitDirection = "clockwise" | "anticlockwise" | "figure-of-eight";

export interface CircuitEntry {
  id: string;
  /** Official circuit name (Wikipedia list). */
  name: string;
  /** Common short name for headings (editorial label). */
  shortName: string;
  openf1: { circuitKey: number; shortName: string };
  locality: string;
  country: string;
  countryCode: string | null;
  type: CircuitType | null;
  direction: CircuitDirection | null;
  /** Length of the last configuration used in F1 (km), as published. */
  lengthKm: number | null;
  turns: number | null;
  lapRecord: { time: string; driver: string | null; car: string | null; year: number | null; layoutLengthKm: number } | null;
  grandsPrix: Array<{ year: number; name: string; officialName: string; date: string }>;
  /** current: on the 2026 calendar (OpenF1 meetings); previous: hosted a Grand Prix in 2023-2025 only. */
  calendar: "current" | "previous";
  season2026: "held" | "upcoming" | "not-held" | null;
  wikipedia: string;
  geometry: { file: string; sessionKeys: number[]; scale: "assumed" | "within-tolerance" | "caveat" | null; verdict: string | null } | null;
}

export interface CatalogSource {
  name: string;
  url: string;
  accessed: string;
  fields: string[];
  note?: string;
}

export const CATALOG = data as unknown as { schema: string; generatedOn: string; scope: string; sources: CatalogSource[]; circuits: CircuitEntry[] };
export const CIRCUITS: readonly CircuitEntry[] = CATALOG.circuits;

export const findCircuitById = (id: string) => CIRCUITS.find((c) => c.id === id);
/** The circuit for an OpenF1 circuit short name (as stored in the results snapshots), e.g. "Monte Carlo" -> monaco. */
export const circuitByShortName = (short: string | null | undefined) => (short ? CIRCUITS.find((c) => c.openf1.shortName === short) : undefined);

export const TYPE_LABEL: Record<CircuitType, string> = { street: "Street circuit", permanent: "Permanent circuit", road: "Road circuit" };
export const DIRECTION_LABEL: Record<CircuitDirection, string> = { clockwise: "Clockwise", anticlockwise: "Anticlockwise", "figure-of-eight": "Figure of eight" };
export const SEASON_LABEL: Record<NonNullable<CircuitEntry["season2026"]>, string> = {
  held: "Raced in 2026",
  upcoming: "Later in 2026",
  "not-held": "2026 race not held",
};
